#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// ============================================================================
// QUICKSORT IMPLEMENTATION
// ============================================================================

// Partition function: rearranges array elements around a pivot
// Elements smaller than pivot go to the left, larger to the right
// Returns the final index of the pivot element
int partition(int arr[], int low, int high) {
    // Choose the last element as pivot
    int pivot = arr[high];

    // Index of smaller element (indicates rightmost position of smaller elements)
    int i = low - 1;

    // Traverse through all elements
    for (int j = low; j < high; j++) {
        // If current element is smaller than or equal to pivot
        if (arr[j] <= pivot) {
            // Increment index of smaller element
            i++;

            // Swap arr[i] and arr[j]
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    // Place pivot in correct position (after all smaller elements)
    int temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;

    // Return the partitioning index
    return i + 1;
}

// Quicksort recursive function
// Sorts the array from index low to high
void quicksort(int arr[], int low, int high) {
    // Base case: if subarray has 0 or 1 element, it's already sorted
    if (low < high) {
        // Partition the array and get pivot index
        int pi = partition(arr, low, high);

        // Recursively sort elements before partition
        quicksort(arr, low, pi - 1);

        // Recursively sort elements after partition
        quicksort(arr, pi + 1, high);
    }
}

// ============================================================================
// MERGE SORT IMPLEMENTATION
// ============================================================================

// Merge function: merges two sorted subarrays into one sorted array
// arr[low..mid] and arr[mid+1..high] are the two sorted subarrays
void merge(int arr[], int low, int mid, int high) {
    // Calculate sizes of two subarrays to be merged
    int n1 = mid - low + 1;
    int n2 = high - mid;

    // Create temporary arrays to hold the two subarrays
    int *left = (int *)malloc(n1 * sizeof(int));
    int *right = (int *)malloc(n2 * sizeof(int));

    // Copy data to temporary arrays
    for (int i = 0; i < n1; i++) {
        left[i] = arr[low + i];
    }
    for (int j = 0; j < n2; j++) {
        right[j] = arr[mid + 1 + j];
    }

    // Merge the temporary arrays back into arr[low..high]
    int i = 0;      // Initial index of first subarray
    int j = 0;      // Initial index of second subarray
    int k = low;    // Initial index of merged subarray

    // Compare elements from both subarrays and place smaller one in arr
    while (i < n1 && j < n2) {
        if (left[i] <= right[j]) {
            arr[k] = left[i];
            i++;
        } else {
            arr[k] = right[j];
            j++;
        }
        k++;
    }

    // Copy remaining elements of left[] if any
    while (i < n1) {
        arr[k] = left[i];
        i++;
        k++;
    }

    // Copy remaining elements of right[] if any
    while (j < n2) {
        arr[k] = right[j];
        j++;
        k++;
    }

    // Free allocated memory
    free(left);
    free(right);
}

// Mergesort recursive function
// Sorts the array from index low to high
void mergesort(int arr[], int low, int high) {
    // Base case: if subarray has 0 or 1 element, it's already sorted
    if (low < high) {
        // Find the middle point to divide the array into two halves
        int mid = low + (high - low) / 2;

        // Recursively sort the first half
        mergesort(arr, low, mid);

        // Recursively sort the second half
        mergesort(arr, mid + 1, high);

        // Merge the two sorted halves
        merge(arr, low, mid, high);
    }
}

// ============================================================================
// BENCHMARK HARNESS
// ============================================================================

// Number of iterations for each test to get more accurate timing
#define ITERATIONS 10

// Function to create a random array of given size
int* createRandomArray(int size) {
    int *arr = (int *)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        // Generate random numbers between 0 and 100000
        arr[i] = rand() % 100000;
    }
    return arr;
}

// Function to copy array (for testing both algorithms on same data)
int* copyArray(int *src, int size) {
    int *dest = (int *)malloc(size * sizeof(int));
    memcpy(dest, src, size * sizeof(int));
    return dest;
}

// Function to verify array is sorted
int isSorted(int arr[], int size) {
    for (int i = 0; i < size - 1; i++) {
        if (arr[i] > arr[i + 1]) {
            return 0;
        }
    }
    return 1;
}

// Function to benchmark quicksort
double benchmarkQuicksort(int arr[], int size) {
    clock_t start, end;
    double timeSpent;

    // Start timing
    start = clock();

    // Run quicksort multiple times for accurate measurement
    for (int i = 0; i < ITERATIONS; i++) {
        quicksort(arr, 0, size - 1);
    }

    // End timing
    end = clock();

    // Calculate average time in milliseconds
    timeSpent = ((double)(end - start) / CLOCKS_PER_SEC) * 1000.0 / ITERATIONS;

    return timeSpent;
}

// Function to benchmark mergesort
double benchmarkMergesort(int arr[], int size) {
    clock_t start, end;
    double timeSpent;

    // Start timing
    start = clock();

    // Run mergesort multiple times for accurate measurement
    for (int i = 0; i < ITERATIONS; i++) {
        mergesort(arr, 0, size - 1);
    }

    // End timing
    end = clock();

    // Calculate average time in milliseconds
    timeSpent = ((double)(end - start) / CLOCKS_PER_SEC) * 1000.0 / ITERATIONS;

    return timeSpent;
}

// Function to print benchmark results in a table format
void printBenchmarkTable(int sizes[], int numSizes, 
                         double quicksortTimes[], double mergesortTimes[]) {
    printf("\n");
    printf("================================================================================\n");
    printf("                         SORTING ALGORITHM BENCHMARK RESULTS\n");
    printf("================================================================================\n");
    printf("  Array Size  |  Quicksort (ms)  |  Mergesort (ms)  |  Quicksort/Mergesort Ratio\n");
    printf("--------------------------------------------------------------------------------\n");

    for (int i = 0; i < numSizes; i++) {
        double ratio = mergesortTimes[i] > 0 ? quicksortTimes[i] / mergesortTimes[i] : 0;
        printf("  %10d  |  %15.4f  |  %15.4f  |  %15.4f\n", 
               sizes[i], quicksortTimes[i], mergesortTimes[i], ratio);
    }

    printf("================================================================================\n");
    printf("  Note: Lower time is better. Ratio < 1 means Quicksort is faster.\n");
    printf("================================================================================\n");
}

// Main function to run benchmark tests
int main() {
    // Seed random number generator
    srand(time(NULL));

    // Array sizes to test
    int sizes[] = {100, 1000, 10000};
    int numSizes = sizeof(sizes) / sizeof(sizes[0]);

    // Arrays to store benchmark results
    double quicksortTimes[numSizes];
    double mergesortTimes[numSizes];

    printf("Running sorting algorithm benchmarks...\n");
    printf("Each test runs %d iterations for accurate timing.\n\n", ITERATIONS);

    // Run benchmarks for each array size
    for (int i = 0; i < numSizes; i++) {
        int size = sizes[i];

        // Create random array for this size
        int *originalArray = createRandomArray(size);

        // Create copies for each algorithm
        int *quicksortArray = copyArray(originalArray, size);
        int *mergesortArray = copyArray(originalArray, size);

        // Benchmark quicksort
        quicksortTimes[i] = benchmarkQuicksort(quicksortArray, size);

        // Benchmark mergesort
        mergesortTimes[i] = benchmarkMergesort(mergesortArray, size);

        // Verify both algorithms produced sorted arrays
        if (!isSorted(quicksortArray, size)) {
            printf("ERROR: Quicksort failed to sort array of size %d!\n", size);
        }
        if (!isSorted(mergesortArray, size)) {
            printf("ERROR: Mergesort failed to sort array of size %d!\n", size);
        }

        // Free memory
        free(originalArray);
        free(quicksortArray);
        free(mergesortArray);

        printf("Completed benchmark for size %d\n", size);
    }

    // Print results in table format
    printBenchmarkTable(sizes, numSizes, quicksortTimes, mergesortTimes);

    // Print summary
    printf("\nSUMMARY:\n");
    printf("--------\n");
    printf("Quicksort: O(n log n) average, O(n²) worst case, in-place\n");
    printf("Mergesort: O(n log n) guaranteed, O(n) extra space, stable\n");
    printf("\nFor random data, Quicksort typically performs better due to:\n");
    printf("  - Lower constant factors\n");
    printf("  - Better cache locality\n");
    printf("  - No extra memory allocation\n");
    printf("\nMergesort is preferred when:\n");
    printf("  - Stable sorting is required\n");
    printf("  - Worst-case performance matters\n");
    printf("  - Working with linked lists\n");

    return 0;
}
